-- Rollback-only regression test. Requires at least two Auth users.
begin; create temp table creator_test as select id owner,(select id from auth.users where id<>u.id limit 1) member,gen_random_uuid() team from auth.users u limit 1; grant select on creator_test to authenticated; insert into public.teams(id,name,created_by) select team,'Creator security test',owner from creator_test; insert into public.team_members(team_id,user_id,role) select team,member,'admin' from creator_test; select set_config('request.jwt.claims',json_build_object('sub',member,'role','authenticated')::text,true) from creator_test; set local role authenticated; do $$ declare t record; n int; begin select * into t from creator_test; delete from public.teams where id=t.team; get diagnostics n=row_count; if n<>0 then raise exception 'Noncreator deletion allowed'; end if; begin delete from public.team_members where team_id=t.team and user_id=t.owner; raise exception 'Creator removal allowed'; exception when raise_exception then if sqlerrm<>'The Team creator cannot be removed' then raise; end if; end; begin update public.team_members set role='member' where team_id=t.team and user_id=t.owner; raise exception 'Creator demotion allowed'; exception when raise_exception then if sqlerrm<>'The Team creator must remain an administrator' then raise; end if; end; end $$; reset role; select set_config('request.jwt.claims',json_build_object('sub',owner,'role','authenticated')::text,true) from creator_test; set local role authenticated; do $$ declare n int; begin delete from public.teams where id=(select team from creator_test); get diagnostics n=row_count; if n<>1 then raise exception 'Creator deletion broken'; end if; end $$; reset role; rollback;